} impl ReflectService { pub fn notify(&self, changed: TypeId) { // BFS walk dependents let deps = self.dependents.read().get(&changed).cloned().unwrap_or_default(); for fid in deps { if let Some(sender) = self.notifiers.read().get(&changed) { let _ = sender.send(()); // fan-out, ignore closed receivers } // also trigger Fiber::refresh via task tokio::spawn({ let fiber = self.fiber_for(fid); async move { fiber.refresh().await } }); } }
